for slug,(challenge,direction,outcome) in notes.items():
    p=d/'work'/slug/'index.html'; s=p.read_text(encoding='utf-8')
    s=s.replace('<h2>Purpose.</h2>','<h2>The brief.</h2>')
    s=s.replace('</p></article><article><h2>Design direction.</h2>','</p><h3>The challenge</h3><p>'+html.escape(challenge)+'</p></article><article><h2>Design direction.</h2>',1)
    s=s.replace('Explore the original page compositions below: the cover establishes the visual direction, while the selected interior pages demonstrate how the content is organised across the publication.',html.escape(direction))
    s=s.replace('<h2>Source and format.</h2>','<h2>Source and format.</h2><h3>Intended outcome</h3><p>'+html.escape(outcome)+'</p>')
    p.write_text(s,encoding='utf-8')
print('Expanded 40 distinct project narratives')
